$categories=mpi_db()->query('SELECT id,name,description,image_path FROM categories WHERE visible=1 ORDER BY sort_order,id')->fetchAll();
$products=mpi_db()->query('SELECT p.id,p.category_id,p.name,p.sku,p.description,p.base_price,p.unit,p.image_path,p.variants_json,c.name AS category_name FROM products p JOIN categories c ON c.id=p.category_id WHERE p.visible=1 AND c.visible=1 ORDER BY p.featured DESC,p.sort_order,p.id DESC LIMIT 300')->fetchAll();
$clientProducts=[];foreach($products as $p){$variants=json_decode($p['variants_json'],true);if(!is_array($variants))$variants=[];$clientProducts[]=['id'=>(int)$p['id'],'name'=>$p['name'],'sku'=>$p['sku'],'price'=>(float)$p['base_price'],'unit'=>$p['unit'],'category'=>(int)$p['category_id'],'variants'=>$variants];}
